// Writes lighting/generated/recipes.ts and recipes.json from the canonical source.
// Run with --check to fail if generated files are stale.
import { writeFileSync, readFileSync, existsSync } from 'node:fs';
import { load, validate, catalogue } from './recipes-lib.mjs';

const doc = load();
const errors = validate(doc);
if (errors.length) { console.error(errors.join('\n')); process.exit(1); }
const cat = catalogue(doc);
const json = JSON.stringify(cat, null, 2) + '\n';
const ts = `// GENERATED by lighting/scripts/generate.mjs from lighting/recipes/recipes.json. Do not edit.\nexport const RECIPES = ${JSON.stringify(cat, null, 2)} as const;\nexport type RecipeId = (typeof RECIPES)[number]['id'];\n`;
const out = { 'lighting/generated/recipes.json': json, 'lighting/generated/recipes.ts': ts };
const root = new URL('../../', import.meta.url);
let stale = false;
for (const [p, body] of Object.entries(out)) {
  const f = new URL(p, root);
  if (process.argv.includes('--check')) {
    if (!existsSync(f) || readFileSync(f, 'utf8') !== body) { console.error(`stale: ${p}`); stale = true; }
  } else writeFileSync(f, body);
}
process.exit(stale ? 1 : 0);
